def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    my_last, opp_last = history[-1]
    if n == 2:
        return 'D' if opp_last == 'D' else 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    total_opp_def = opp.count('D')

    if total_opp_def == 0:
        if n >= 97:
            return 'D'
        return 'C'
    if total_opp_def == n:
        return 'D'

    opp_def_recent = opp[-5:].count('D')
    me_def_recent = me[-5:].count('D')

    opp_after_my_C = 0
    opp_after_my_C_D = 0
    opp_after_my_D = 0
    opp_after_my_D_D = 0
    for i in range(n - 1):
        if me[i] == 'C':
            opp_after_my_C += 1
            if opp[i + 1] == 'D':
                opp_after_my_C_D += 1
        else:
            opp_after_my_D += 1
            if opp[i + 1] == 'D':
                opp_after_my_D_D += 1
    p_d_after_c = opp_after_my_C_D / opp_after_my_C if opp_after_my_C > 0 else 0.0
    p_d_after_d = opp_after_my_D_D / opp_after_my_D if opp_after_my_D > 0 else 0.0

    if n >= 90:
        if opp_def_recent <= 2:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    if opp_def_recent <= 1 and n < 90:
        if n % 19 == 0:
            return 'D'
        return 'C'

    if p_d_after_d > p_d_after_c + 0.2:
        return 'C'

    if n > 25 and p_d_after_c > p_d_after_d + 0.2:
        return 'D'

    if opp_last == 'D':
        if n >= 3 and opp[-3:].count('D') >= 2:
            return 'D'
        if opp_def_recent >= 4:
            return 'D'
        if me_def_recent >= 3 and opp_def_recent <= 2:
            return 'C'
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    if n > 12 and opp_def_recent <= 2 and rng.random() < 0.07:
        return 'D'

    return 'C'
